const REPO='ins0dus/riftbound-coach';const MAX_BODY=8000;const recent=new Map();const cors={'Access-Control-Allow-Origin':'https://play.riftatlas.com','Access-Control-Allow-Methods':'POST, OPTIONS','Access-Control-Allow-Headers':'content-type'};const reply=(status,obj)=>new Response(JSON.stringify(obj),{status,headers:{'content-type':'application/json',...cors}});export default{async fetch(req,env){if(req.method==='OPTIONS')return new Response(null,{headers:cors});if(req.method!=='POST')return reply(405,{error:'POST only'});const ip=req.headers.get('cf-connecting-ip')||'x';const now=Date.now();const hits=(recent.get(ip)||[]).filter((t)=>now-t<3600e3);if(hits.length>=20)return reply(429,{error:'Too many reports this hour'});hits.push(now);recent.set(ip,hits);let data;try{data=await req.json();}catch(e){return reply(400,{error:'Bad JSON'});}let{title,body,version}=data||{};if(typeof title!=='string'||!title.startsWith('[feedback]')||typeof body!=='string')return reply(400,{error:'Not a coach report'});title=title.slice(0,120);body=body.slice(0,MAX_BODY)+'\n\n_Coach '+String(version||'?').slice(0,12)+' - sent via feedback server_';const r=await fetch('https://api.github.com/repos/'+REPO+'/issues',{method:'POST',headers:{authorization:'Bearer '+env.GITHUB_TOKEN,accept:'application/vnd.github+json','user-agent':'rb-coach-feedback','content-type':'application/json'},body:JSON.stringify({title,body})});if(!r.ok)return reply(502,{error:'GitHub said '+r.status});const j=await r.json();return reply(201,{ok:true,issue:j.number});}};
